mapper.select:
select aus.id as authorId, aus.nickname as authorName, aps.*
from author_privilege_set aps
left JOIN author_user aus on aus.id = aps.author_id and aus.deleted = 0
where aps.parent_id = 0
and aps.deleted = 0

    and aps.author_id in

        #{item}



    and aps.author_id =#{reqVO.authorId}


    and aps.name like concat('%',#{reqVO.name},'%')


    and aps.review_status = #{reqVO.reviewStatus}


    and aps.`status` = #{reqVO.status}


    and aps.fast_buy = #{reqVO.fastBuy}


    and aps.`type` = #{reqVO.type}


    AND aps.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


    AND aps.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}

order by aps.id desc
